// Success: nothing to notify -- the platform has already told each head. A clean run is silent, same posture as every
// other clear-on-success flow in this repo; the summary is only for the execution log.
const body = $input.first().json.body ?? $input.first().json;
return [{ json: { ok: true, period: body.period ?? null, evaluatedUnits: body.evaluatedUnits ?? null, told: (body.told ?? []).length, alertsOpened: body.alertsOpened ?? null, alertsResolved: body.alertsResolved ?? null, unitsWithoutHead: body.unitsWithoutHead ?? [] } }];

// Dead-letter payload for the error branch -- retries (x3) already exhausted at this point.
const err = $input.first().json.error ?? $input.first().json;
return [{ json: { error: String(err?.message ?? err) } }];
